import sys

def solve():
    data = sys.stdin.read().split()
    l = int(data[0])
    r = int(data[1])

    n = 9
    ten = [1] * (n + 1)
    for i in range(1, n + 1):
        ten[i] = 10 * ten[i - 1]

    answer = 0

    lucky_numbers = []

    for length in range(1, n + 1):
        for cur in range(1 << length):
            value = 0
            for j in range(length):
                if ((1 << j) & cur) == (1 << j):
                    value += ten[j] * 7
                else:
                    value += ten[j] * 4
            lucky_numbers.append(value)

    lucky_numbers.append(4444444444)

    last_number = l

    for lucky_number in lucky_numbers:
        if lucky_number > r:
            answer += (r - last_number + 1) * lucky_number
            break
        if lucky_number >= l:
            answer += (lucky_number - last_number + 1) * lucky_number
            last_number = lucky_number + 1

    print(answer)

if __name__ == "__main__":
    solve()
